let url = null;

// Ưu tiên 1: Lấy ảnh từ Edit Fields (lần sửa cuối cùng)
try {
  const editFields = $('Edit Fields').all();
  if (editFields.length > 0) {
    url = editFields[editFields.length - 1].json.data.resultJson.resultUrls[0];
  }
} catch (e) {
  // Edit Fields chưa chạy, bỏ qua
}

// Ưu tiên 2: Nếu không có ảnh sửa, lấy từ Edit Fields3 (ảnh lần đầu)
if (!url) {
  try {
    const editFields3 = $('Edit Fields3').all();
    if (editFields3.length > 0) {
      url = editFields3[editFields3.length - 1].json.data.resultJson.resultUrls[0];
    }
  } catch (e) {
    url = null;
  }
}

return [{ json: { imageUrl: url } }];

const items = $('Aggregate').first().json.images;
const promptText = $('get imformation post').first().json.prompt;

const imageLines = items.map(item =>
  `"https://drive.google.com/uc?export=download&id=${item.id}"`
).join(',\n        ');

const jsonString = `{
  "model": "gpt-image-2-image-to-image",
  "input": {
    "prompt": "${promptText}",
    "input_urls": [
      ${imageLines}
    ],
    "aspect_ratio": "1:1"
  }
}`;

return [{ json: { body: jsonString } }];

const content = $('Get row(s) in sheet1').first().json.content;
