return items.map(item => {
  const files = item.json; // mỗi item là 1 file
  return {
    json: {
      ...files,
      download_url: `https://drive.google.com/uc?export=download&id=${files.id}`
    }
  };
});

// Noi dung bai viet lay tu Google Sheet
const content = $('Get row(s) in sheet').first().json.content;

// Lay TAT CA asset URN tu node Register Upload (moi anh = 1 asset)
const assets = $('Register Upload').all();

// Tao mang media nhieu anh, dung thu tu da sort
const media = assets.map(item => ({
  status: "READY",
  media: item.json.value.asset
}));

const body = {
  author: "urn:li:person:agqvuCYbZQ",
  lifecycleState: "PUBLISHED",
  specificContent: {
    "com.linkedin.ugc.ShareContent": {
      shareCommentary: { text: content },
      shareMediaCategory: "IMAGE",
      media: media
    }
  },
  visibility: {
    "com.linkedin.ugc.MemberNetworkVisibility": "PUBLIC"
  }
};

return [{ json: { body: JSON.stringify(body) } }];
